        let defaultTrack: Track = Track()
        defaultTrack.index = -1.0
        let defaultStaff: Staff = Staff()
        defaultStaff.index = -1.0
        let defaultBar: Bar = Bar()
        defaultBar.id = -1.0
        defaultBar.index = -1.0
        let defaultVoice: Voice = Voice()
        defaultVoice.id = -1.0
        defaultVoice.index = -1.0
