            let staves: List<Map<String, Any?>> = TypeHelper.unknownToList(track.get("staves"), Map<String, Any?>.self)
            for staff in staves {
                let bars: List<Map<String, Any?>> = TypeHelper.unknownToList(staff.get("bars"), Map<String, Any?>.self)
                for bar in bars {
