                        }
                        try ScoreSerializerPlugin._sanitizeJson(voice, self._defaultVoiceJson, "Voice")
                    }
                    try ScoreSerializerPlugin._sanitizeJson(bar, self._defaultBarJson, "Bar")
                }
                try ScoreSerializerPlugin._sanitizeJson(staff, self._defaultStaffJson, "Staff")
