                            isEqual = (dv as! Int16Array).length == 0.0 && (v as! Int16Array).length == 0.0
                        } else if dv is Int32Array && v is Int32Array {
                            isEqual = (dv as! Int32Array).length == 0.0 && (v as! Int32Array).length == 0.0
                        } else if dv is Uint8Array && v is Uint8Array {
                            isEqual = (dv as! Uint8Array).length == 0.0 && (v as! Uint8Array).length == 0.0
                        } else if dv is Uint16Array && v is Uint16Array {
                            isEqual = (dv as! Uint16Array).length == 0.0 && (v as! Uint16Array).length == 0.0
                        } else if dv is Uint32Array && v is Uint32Array {
                            isEqual = (dv as! Uint32Array).length == 0.0 && (v as! Uint32Array).length == 0.0
                        } else if Array.isArray(dv) && Array.isArray(v) {
                            isEqual = TestPlatform.typedArrayAsUnknownArray(dv).length == 0.0 && TestPlatform.typedArrayAsUnknownArray(v).length == 0.0
                        } else if dv is any _AnyMap && v is any _AnyMap {
                            try ScoreSerializerPlugin._sanitizeJson((v as! Map<String, Any?>), (dv as! Map<String, Any?>))
                            if (v as! Map<String, Any?>).size == 0.0 {
                                isEqual = true
                            }
                        } else {
                            try isEqual = ScoreSerializerPluginPartials._isPlatformTypeEqual(v, dv)
                        }
                    default:
                        break
                    }
                }
                if !isEqual {
                    modelJson.set(k, v)
                }
            } else {
                modelJson.set(k, v)
            }
        }
    }
}

internal final class SnapshotFileRepository {
    nonisolated(unsafe) private static var _cache: Map<String, SnapshotFile> = Map<String, SnapshotFile>()

    public static func loadSnapshotFile(_ path: String) throws -> SnapshotFile {
        var file: SnapshotFile? = SnapshotFileRepository._cache.get(path)
        if !TypeHelper.isTruthy(file) {
            file = SnapshotFile()
            try file!.loadFrom(path)
            SnapshotFileRepository._cache.set(path, file!)
        }
        return file!
    }

    public init() {}
}

internal final class SnapshotFile {
    private static func _createConfig() -> PrettyFormatConfig {
        let c: PrettyFormatConfig = PrettyFormatConfig()
        c.plugins.push(ScoreSerializerPlugin.instance)
        c.plugins.push(MidiEventSerializerPlugin.instance)
        c.plugins.push(AlphaTexDiagnosticPlugin.instance)
        c.plugins.push(AlphaTexAstNodePlugin.instance)
        return c
    }

    nonisolated(unsafe) private static let _matchOptions: PrettyFormatConfig = SnapshotFile._createConfig()

    public var snapshots: Map<String, String> = Map<String, String>()

    /**
     * Matches the given snapshot with the contained one.
     */
    public func match(_ name: String, _ value: Any?) throws -> String? {
        let expected: List<String>? = self.snapshots.get(name)?.splitBy("\n")
        if expected == nil {
            return "No snapshot '\((name).toTemplate())' found"
        }
        let actual: List<String> = try SnapshotFile._printBacktickString(PrettyFormat.format(value, SnapshotFile._matchOptions)).splitBy("\n")
        let lines: Double = Math.min(expected!.length, actual.length)
        let errors: List<String> = List<String>()
        if expected!.length != actual.length {
            errors.push("Expected \((expected!.length).toTemplate()) lines, but only got \((actual.length).toTemplate())")
        }
        do {
            var i: Double = 0.0
            while i < lines {
                if actual[(i).toInt()].trimEnd() != expected![(i).toInt()].trimEnd() {
                    errors.push("Error on line \((i + 1.0).toTemplate()): ")
                    errors.push("+ \((actual[(i).toInt()]).toTemplate())")
                    errors.push("- \((expected![(i).toInt()]).toTemplate())")
                }
                i += 1
            }
        }
        if errors.length > 0 {
            return errors.join("\n")
        }
        return nil
    }

    private static func _printBacktickString(_ str: String) -> String {
        return SnapshotFile._escapeBacktickString(str)
    }

    private static func _escapeBacktickString(_ str: String) -> String {
        return str.replaceAll(TypeHelper.createRegex("[`\\\\]", "g"), { (substring: String) -> String in
            return "\\\((substring).toTemplate())"
        })
    }

    public func loadFrom(_ path: String) throws {
        let content: String = TestPlatform.loadFileAsStringSync(path)
        let lines: List<String> = content.splitBy("\n")
        var i: Double = 0.0
        while i < lines.length {
            if lines[(i).toInt()].startsWith("exports[`") {
                let endOfName: Double = lines[(i).toInt()].indexOfInDouble("`]", 9.0)
                if endOfName == -1.0 {
                    throw JsError("Failed to parse snapshot file, missing `] on line \((i + 1.0).toTemplate())")
                }
                let name: String = lines[(i).toInt()].substring(9.0, endOfName)
                if lines[(i).toInt()].trimEnd().endsWith("`;") {
                    let startOfValue: Double = lines[(i).toInt()].indexOfInDouble("`", endOfName + 2.0) + 1.0
                    let endOfValue: Double = lines[(i).toInt()].indexOfInDouble("`;", startOfValue + 1.0)
                    self.snapshots.set(name, lines[(i).toInt()].substring(startOfValue, endOfValue))
                    i += 1
                    continue
                }
                i += 1
                var value: String = ""
                while i < lines.length {
                    let line: String = lines[(jsPostInc(&i)).toInt()]
                    if line.startsWith("`;") {
                        break
                    }
                    value += "\((line.trimEnd()).toTemplate())\n"
                }
                self.snapshots.set(name, value.trimEnd())
            } else {
                i += 1
            }
        }
    }

    public init() {}
}

internal protocol PrettyFormatNewPlugin: AnyObject {
    func serialize(_ val: Any?, _ config: PrettyFormatConfig, _ indentation: String, _ depth: Double, _ refs: List<Any?>, _ printer: @escaping PrettyFormatPrinter) throws -> String

    func test(_ arg0: Any?) -> Bool
}
